-- ===== Guard: abort before any change unless this is the expected database in the expected state =====
DO $guard$
DECLARE
  outside integer;
BEGIN
  IF (SELECT system_identifier::text FROM pg_control_system()) IS DISTINCT FROM '7678069749886157684' THEN
    RAISE EXCEPTION 'GATE_C4H1_WRONG_DATABASE: system identifier %', (SELECT system_identifier::text FROM pg_control_system());
  END IF;
  IF current_database() IS DISTINCT FROM 'postgres' THEN
    RAISE EXCEPTION 'GATE_C4H1_WRONG_DATABASE: database %', current_database();
  END IF;
  IF (SELECT max(version) FROM supabase_migrations.schema_migrations) IS DISTINCT FROM '20261121090000' THEN
    RAISE EXCEPTION 'GATE_C4H1_UNEXPECTED_HISTORY: latest is %', (SELECT max(version) FROM supabase_migrations.schema_migrations);
  END IF;
  IF (SELECT count(*) FROM pg_constraint WHERE conrelid = 'public.campaigns'::regclass
        AND conname IN ('campaigns_retry_statuses_allowed', 'campaigns_retry_after_minutes_range')) <> 0 THEN
    RAISE EXCEPTION 'GATE_C4H1_OBJECTS_ALREADY_EXIST: a retry constraint already exists';
  END IF;
  -- GATE C1 is in place (this migration builds on its campaign engine).
  IF to_regprocedure('public.admit_campaign_outbound_call(uuid, uuid, uuid, text, integer, integer, timestamptz, text, text)') IS NULL
     OR NOT EXISTS (SELECT 1 FROM public.platform_settings WHERE key = 'outbound.calling_paused') THEN
    RAISE EXCEPTION 'GATE_C4H1_PRECONDITION: the GATE C1 campaign engine is not in place';
  END IF;
  -- Every existing campaign already satisfies the limits (ADD CONSTRAINT would fail anyway; this names the reason).
  SELECT count(*) INTO outside FROM public.campaigns
   WHERE NOT (retry_statuses <@ ARRAY['no_answer', 'busy', 'failed']::text[])
      OR retry_after_minutes NOT BETWEEN 15 AND 10080;
  IF outside <> 0 THEN
    RAISE EXCEPTION 'GATE_C4H1_PRECONDITION: % campaign(s) outside the retry limits; review them first', outside;
  END IF;
  PERFORM set_config('gate_c4h1.data_before', md5((SELECT 'campaigns:' || count(*) || ':' || coalesce(md5(string_agg(to_jsonb(x)::text, '|' ORDER BY to_jsonb(x)::text)), '-') FROM public.campaigns x) || ';' || (SELECT 'campaign_contacts:' || count(*) || ':' || coalesce(md5(string_agg(to_jsonb(x)::text, '|' ORDER BY to_jsonb(x)::text)), '-') FROM public.campaign_contacts x) || ';' || (SELECT 'phone_numbers:' || count(*) || ':' || coalesce(md5(string_agg(to_jsonb(x)::text, '|' ORDER BY to_jsonb(x)::text)), '-') FROM public.phone_numbers x) || ';' || (SELECT 'agent_configs:' || count(*) || ':' || coalesce(md5(string_agg(to_jsonb(x)::text, '|' ORDER BY to_jsonb(x)::text)), '-') FROM public.agent_configs x) || ';' || (SELECT 'platform_settings:' || count(*) || ':' || coalesce(md5(string_agg(to_jsonb(x)::text, '|' ORDER BY to_jsonb(x)::text)), '-') FROM public.platform_settings x)), true);
END
$guard$;

-- ===== The migration, byte for byte (supabase/migrations/20261122090000_campaign_retry_limits.sql) =====
-- Campaign retry limits (GATE C4 audit finding H1).
--
-- Customers may write a draft campaign's retry settings directly (column
-- grants on campaigns), and nothing limited them: retry_statuses could
-- include 'completed' and retry_after_minutes could be 0 or negative, so a
-- person who answered could be called again every minute up to max_attempts.
--
-- From now on, in the database itself:
--   - only an unanswered attempt is retried: retry_statuses holds only
--     'no_answer', 'busy' and 'failed' (an empty list means no retries);
--   - a retry waits at least 15 minutes, and at most 7 days.
-- The application applies the same limits (campaign-outcome.ts) and launch
-- refuses a campaign outside them, so rows from before this migration are
-- held to them too.
--
-- Production had 0 campaigns when this was written; ADD CONSTRAINT validates
-- every existing row and fails (changing nothing) if any is outside the limits.

ALTER TABLE public.campaigns DROP CONSTRAINT IF EXISTS campaigns_retry_statuses_allowed;
ALTER TABLE public.campaigns
  ADD CONSTRAINT campaigns_retry_statuses_allowed CHECK (
    retry_statuses <@ ARRAY['no_answer', 'busy', 'failed']::text[]
  );

ALTER TABLE public.campaigns DROP CONSTRAINT IF EXISTS campaigns_retry_after_minutes_range;
ALTER TABLE public.campaigns
  ADD CONSTRAINT campaigns_retry_after_minutes_range CHECK (
    retry_after_minutes BETWEEN 15 AND 10080
  );

